// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.lang.reflect.Method;

import org.junit.jupiter.api.Test;

class FrontierStatisticsBuildConfigTest {

	private static final long MIB = 1024L * 1024L;
	private static final long GIB = 1024L * MIB;

	@Test
	void twentyBillionProfileFitsTheTwoGiBGovernorContract() {
		FrontierStatisticsBuildConfig profile = FrontierStatisticsBuildConfig.forDiskBudget(128L * GIB);

		assertEquals(16L * GIB, profile.exactAndLinearBudgetBytes());
		assertEquals(32L * GIB, profile.leafWitnessBudgetBytes());
		assertEquals(1 << 14, profile.cellCount(), "the Omni paper profile uses 2^14 cells per row");
		assertEquals(1 << 18, profile.countMinWidth(),
				"the secondary linear estimator scales independently of Omni cells");
		assertEquals(64L * MIB, profile.sortMemoryBytes());

		long estimatedHeap = FrontierStatisticsBuilder.estimatedHeapBytes(profile);
		assertTrue(estimatedHeap <= 1280L * MIB,
				() -> "builder estimate exceeds the 1.25 GiB background envelope: " + estimatedHeap);
		FrontierStatisticsHeapGovernor governor = FrontierStatisticsHeapGovernor.forBudget(2L * GIB);
		try (FrontierStatisticsHeapGovernor.Lease lease = governor.tryAcquire(
				FrontierStatisticsMemoryPurpose.BUILDER, estimatedHeap)) {
			assertNotNull(lease);
		}
	}

	@Test
	void smallStoreProfileScalesMatricesAndSortBuffersDown() {
		FrontierStatisticsBuildConfig profile = FrontierStatisticsBuildConfig.forDiskBudget(32L * MIB);

		assertEquals(1 << 5, profile.cellCount(),
				"small profiles must reserve deletion-safe witnesses before increasing the cell width");
		assertEquals(1 << 11, profile.countMinWidth());
		assertEquals(1L * MIB, profile.sortMemoryBytes());
		assertTrue(FrontierStatisticsBuilder.estimatedHeapBytes(profile) < 512L * MIB);
	}

	@Test
	void diskProfileIsAdaptedToTheGlobalHeapAlongsideAMappedGeneration() throws Exception {
		long heapBudget = 64L * MIB;
		Method forBudgets = FrontierStatisticsBuildConfig.class.getMethod(
				"forBudgets", long.class, long.class);
		FrontierStatisticsBuildConfig profile = (FrontierStatisticsBuildConfig) forBudgets.invoke(
				null, 512L * MIB, heapBudget);
		FrontierStatisticsHeapGovernor governor = FrontierStatisticsHeapGovernor.forBudget(heapBudget);

		assertEquals(512, profile.cellCount(),
				"heap adaptation should preserve the primary Omni cell resolution before auxiliary matrices");
		assertEquals(128, profile.fastAgmsWidth(),
				"the independent linear join fallback must retain its configured contraction width");
		try (FrontierStatisticsHeapGovernor.Lease mapped = governor.tryAcquire(
				FrontierStatisticsMemoryPurpose.MAPPED_METADATA, heapBudget / 3L)) {
			assertNotNull(mapped, "the active query-ready generation retains its metadata while rebuilding");
			try (FrontierStatisticsHeapGovernor.Lease builder = governor.tryAcquire(
					FrontierStatisticsMemoryPurpose.BUILDER,
					FrontierStatisticsBuilder.estimatedHeapBytes(profile))) {
				assertNotNull(builder,
						"the bounded builder must fit without evicting the active mapped generation");
			}
		}
	}

	@Test
	void heapAdmissionAccountsForCompressedQueryReadyHeavyScalarState() {
		FrontierStatisticsBuildConfig smaller = FrontierStatisticsBuildConfig.forDiskBudget(32L * MIB);
		FrontierStatisticsBuildConfig larger = withHeavyPredicateCapacity(
				smaller, Math.addExact(smaller.heavyPredicateCapacity(), 1));

		long actualGrowth = Math.subtractExact(
				FrontierStatisticsBuilder.estimatedHeapBytes(larger),
				FrontierStatisticsBuilder.estimatedHeapBytes(smaller));
		long registerCount = 1L << smaller.hllPrecision();
		long laneWidth = Math.multiplyExact(smaller.totalLaneCount(), smaller.fastAgmsWidth());
		long existingAccumulatorGrowth = Math.addExact(128L,
				Math.addExact(Math.multiplyExact(10L, registerCount), Math.multiplyExact(48L, laneWidth)));
		long queryReadyScalarScratchGrowth = 2L * 13L * Long.BYTES;

		assertTrue(actualGrowth >= Math.addExact(existingAccumulatorGrowth, queryReadyScalarScratchGrowth),
				() -> "builder admission omits query-ready projected-distinct write scratch: growth="
						+ actualGrowth);
	}

	@Test
	void halfGibProfileSizesHeavyPredicatesFromExactTierInsteadOfOmniWidth() {
		FrontierStatisticsBuildConfig profile = FrontierStatisticsBuildConfig.forDiskBudget(512L * MIB);

		assertTrue(profile.heavyPredicateCapacity() >= 512,
				() -> "a 64 MiB exact tier must retain enough bounded-domain predicate refinements: " + profile);
	}

	@Test
	void everyDiskProfileFitsTheDeleteProtectedOmniCellFloor() {
		for (long diskBudget : new long[] { 16L * MIB, 32L * MIB, 512L * MIB, 128L * GIB }) {
			FrontierStatisticsBuildConfig profile = FrontierStatisticsBuildConfig.forDiskBudget(diskBudget);
			long cells = 2L * profile.totalLaneCount() * 4L * profile.omniDepth() * profile.cellCount();
			int retained = FrontierDeleteReserveSizing.retainedCapacity(
					1, Long.MAX_VALUE, profile.deleteReserveFraction(), cells);
			long directoryBytes = Math.multiplyExact(cells, 40L);
			long witnessBytes = Math.multiplyExact(Math.multiplyExact(cells, retained), 64L);

			assertTrue(Math.addExact(directoryBytes, witnessBytes) <= profile.leafWitnessBudgetBytes(),
					() -> "Omni cell floor exceeds leaf envelope for disk budget " + diskBudget
							+ ": width=" + profile.cellCount() + ", cells=" + cells + ", retained=" + retained);
		}
	}

	private static FrontierStatisticsBuildConfig withHeavyPredicateCapacity(
			FrontierStatisticsBuildConfig source, int heavyPredicateCapacity) {
		return new FrontierStatisticsBuildConfig(
				source.diskBudgetBytes(), source.exactAndLinearBudgetBytes(), source.leafWitnessBudgetBytes(),
				source.joinSampleBudgetBytes(), source.adaptiveBudgetBytes(), source.deltaAndManifestBudgetBytes(),
				source.sortMemoryBytes(), source.designLaneCount(), source.auditLaneCount(), source.cellCount(),
				source.omniDepth(), source.witnessFloorPerCell(), source.witnessCeilingPerCell(),
				source.deleteReserveFraction(), source.countMinDepth(), source.countMinWidth(),
				heavyPredicateCapacity, source.hllPrecision(), source.globalWitnessCapacity());
	}

	@Test
	void deleteReserveMeetsThePerShardExhaustionContract() throws Exception {
		int authoritativeWitnesses = 8_192;
		long populatedCells = 2L * 6L * 4L * 3L * (1L << 14);
		double deletionChurn = 0.25d;
		Class<?> sizing = Class.forName(
				"org.eclipse.rdf4j.sail.lmdb.frontier.FrontierDeleteReserveSizing");
		var retainedCapacity = sizing.getDeclaredMethod(
				"retainedCapacity", int.class, long.class, double.class, long.class);
		retainedCapacity.setAccessible(true);
		int retained = (int) retainedCapacity.invoke(
				null, authoritativeWitnesses, 20_000_000_000L, deletionChurn, populatedCells);

		assertTrue(retained > Math.ceil(authoritativeWitnesses / (1.0d - deletionChurn)),
				"meeting the expected survivor count alone leaves about a 50% exhaustion probability");
		double logFailureBound = logBinomialUpperTailBound(
				retained, deletionChurn, retained - authoritativeWitnesses + 1);
		assertTrue(logFailureBound <= Math.log(1.0e-6d / populatedCells),
				() -> "union-bound exhaustion probability is too wide: exp(" + logFailureBound + ")");
	}

	private static double logBinomialUpperTailBound(int trials, double probability, int firstFailure) {
		double fraction = (double) firstFailure / trials;
		double divergence = fraction * Math.log(fraction / probability)
				+ (1.0d - fraction) * Math.log((1.0d - fraction) / (1.0d - probability));
		return -trials * divergence;
	}
}
